      "rank": 1,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "Identifying fading afterglows and establishing cosmological distances transformed gamma-ray bursts from brief enigmas into powerful probes of the distant universe.",
        "attribution": "Costa and Frontera’s BeppoSAX work enabled rapid localization and afterglow detection; Kulkarni’s follow-up helped establish the cosmological interpretation. Credit spans complementary decisive contributions.",
        "maturity": "The observational framework and cosmological origin have been secure for decades and underpin a mature field.",
        "uncertainties": [
          "The boundary between the initial afterglow discovery and the subsequent establishment of the cosmological interpretation complicates the division of credit."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrino astronomy, opening a new observational channel on the universe and demonstrating the power of a detector built on an extraordinary scale.",
        "attribution": "Halzen was a central intellectual and organizational force behind IceCube, but the detector and its results depended on a very large international collaboration.",
        "maturity": "The discovery of an astrophysical high-energy neutrino flux is robust, and subsequent source evidence strengthens the field, though its astronomy is still developing.",
        "uncertainties": [
          "A single-person citation risks underrepresenting the collaboration's central role in detector construction, calibration, and analysis."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Kam-Biu Luk",
        "Yifang Wang"
      ],
      "assessment": {
        "nobel_worthiness": "Measuring a nonzero theta13 completed a crucial part of the neutrino-mixing picture and made searches for leptonic CP violation experimentally accessible.",
        "attribution": "Luk and Wang led the Daya Bay and RENO efforts that independently established the angle. The result was collaborative, and the proposed names represent major experimental leadership.",
        "maturity": "The measurements have been independently confirmed and refined over many years.",
        "uncertainties": [
          "The proposed attribution does not fully capture the broad collaborations or the complementary role of the Double Chooz measurement."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP’s precision full-sky mapping of the microwave background established key cosmological parameters and helped make precision cosmology a quantitative discipline.",
        "attribution": "Bennett and Page supplied central experimental leadership; Spergel made a major contribution to extracting cosmological meaning from the data. The mission’s results were produced by a large team.",
        "maturity": "The measurements have been extensively checked against later observations, including Planck, and their cosmological impact is enduring.",
        "uncertainties": [
          "The distinction between WMAP’s contribution and the earlier COBE discovery, as well as later refinements by Planck, needs careful framing."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers an influential account of the early universe and a compelling origin for primordial structure, with major consequences for cosmology.",
        "attribution": "Guth introduced the inflationary idea; Linde developed important scenarios; Mukhanov helped derive the quantum fluctuations that connect inflation to observable structure.",
        "maturity": "The framework has guided decades of successful cosmological tests, but inflation itself and the mechanism that produced it have not been uniquely established.",
        "uncertainties": [
          "There is no direct, decisive confirmation of inflation or a unique observational signature separating its many versions."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have advanced timekeeping by orders of magnitude and turned atomic clocks into sensitive tools for tests of fundamental physics and relativistic effects.",
        "attribution": "Katori pioneered the lattice-clock approach and Ye made major contributions to its experimental realization and precision. Their contributions are complementary and influential.",
        "maturity": "The technology is highly developed, with independent laboratories achieving exceptional performance, while its full metrological adoption continues.",
        "uncertainties": [
          "The field has many important contributors, and the division of credit for the broad advance from proposal to practical clock merits scrutiny."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Chryssa Kouveliotou",
        "Christopher Thompson",
        "Robert C. Duncan"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetars revealed a distinct class of compact objects whose extreme magnetic fields explain powerful bursts and challenge models of neutron-star physics.",
        "attribution": "Kouveliotou’s observations established the source class, while Thompson and Duncan developed the influential physical model. The case joins discovery and explanation.",
        "maturity": "The magnetar interpretation is well supported across multiple sources and observational channels, with a mature theoretical and observational literature.",
        "uncertainties": [
          "The observational discovery, naming, and theoretical explanation are distinct achievements, making a three-person attribution difficult to delimit."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "Pulsar timing arrays have created a new low-frequency gravitational-wave observatory, with the background signal opening access to the population of massive black-hole binaries.",
        "attribution": "The named researchers made major contributions to pulsar timing and the international array efforts, but the signal emerged through large collaborations and shared analyses.",
        "maturity": "Multiple timing-array collaborations report evidence for a nanohertz background, though its detailed astrophysical interpretation and individual sources remain under study.",
        "uncertainties": [
          "The source population and the strength of the evidence for specific interpretations are not yet settled.",
          "Credit for the emerging result is distributed across international collaborations."
        ]
      }
    }
  ]
